        self.base_checker = BaseChecker(self.mock_linter)

    def test_get_full_documentation_with_all_parameters(self):
        msgs = {
            "C0103": ("C0103", "Invalid name", "Name does not conform to naming conventions")
        }
        options = [
            ("option1", {"default": True, "type": "bool"}, True)
        ]
        reports = [
            ("report1", "Report description", Mock(spec=ReportsCallable))
        ]
        doc = "Additional documentation"
        module = "module_name"
        result = self.base_checker.get_full_documentation(msgs, options, reports, doc, module, True)
        self.assertIn("Invalid name", result)
        self.assertIn("option1", result)
        self.assertIn("Report description", result)
        self.assertIn("Additional documentation", result)
        self.assertIn("module_name", result)

