class BaseWriter:
    def compute_content(self, table):
        # Placeholder for the actual implementation
        pass

    def get_table_content(self, table: Table) -> list[list[str]]:
        content = list(self.compute_content(table))
        rows = []
        for i in range(0, len(content), table.cols):
            row = content[i:i + table.cols]
            if len(row) < table.cols:
                row.extend([''] * (table.cols - len(row)))
            rows.append(row)
        return rows

class TestBaseWriterGetTableContent(unittest.TestCase):
    def setUp(self):
        self.writer = BaseWriter()

    def test_get_table_content_with_complete_rows(self):
        table = Table(cols=3)
        self.writer.compute_content = MagicMock(return_value=[
            "cell1", "cell2", "cell3",
            "cell4", "cell5", "cell6"
        ])

        expected_content = [
            ["cell1", "cell2", "cell3"],
            ["cell4", "cell5", "cell6"]
        ]

        result = self.writer.get_table_content(table)
        self.assertEqual(result, expected_content)

    def test_get_table_content_with_incomplete_rows(self):
        table = Table(cols=3)
        self.writer.compute_content = MagicMock(return_value=[
            "cell1", "cell2",
            "cell3", "cell4", "cell5"
        ])

        expected_content = [
            ["cell1", "cell2", ""],
            ["cell3", "cell4", "cell5"]
        ]

        result = self.writer.get_table_content(table)
        self.assertEqual(result, expected_content)

    def test_get_table_content_with_empty_table(self):
        table = Table(cols=3)
        self.writer.compute_content = MagicMock(return_value=[])

        expected_content = []

        result = self.writer.get_table_content(table)
        self.assertEqual(result, expected_content)

    def test_get_table_content_with_single_row(self):
        table = Table(cols=3)
        self.writer.compute_content = MagicMock(return_value=[
            "cell1", "cell2", "cell3"
        ])

        expected_content = [
            ["cell1", "cell2", "cell3"]
        ]

        result = self.writer.get_table_content(table)
        self.assertEqual(result, expected_content)

    def test_get_table_content_raises_index_error(self):
        table = Table(cols=3)
        self.writer.compute_content = MagicMock(return_value=[
            "cell1", "cell2", "cell3", "cell4"
        ])

        with self.assertRaises(IndexError):
            self.writer.get_table_content(table)

