import unittest
from pylint.graph import get_cycles

class TestGetCycles(unittest.TestCase):

    def test_no_cycles(self):
        graph_dict = {
            'A': {'B'},
            'B': {'C'},
            'C': set()
        }
        self.assertEqual(get_cycles(graph_dict), [])

    def test_single_cycle(self):
        graph_dict = {
            'A': {'B'},
            'B': {'C'},
            'C': {'A'}
        }
        self.assertEqual(get_cycles(graph_dict), [['A', 'B', 'C']])

    def test_multiple_cycles(self):
        graph_dict = {
            'A': {'B'},
            'B': {'C', 'D'},
            'C': {'A'},
            'D': {'E'},
            'E': {'D'}
        }
        cycles = get_cycles(graph_dict)
        self.assertTrue(['A', 'B', 'C'] in cycles)
        self.assertTrue(['D', 'E'] in cycles)
        self.assertEqual(len(cycles), 2)

    def test_disconnected_graph_with_cycle(self):
        graph_dict = {
            'A': {'B'},
            'B': {'A'},
            'C': {'D'},
            'D': set()
        }
        self.assertEqual(get_cycles(graph_dict), [['A', 'B']])

    def test_graph_with_self_loop(self):
        graph_dict = {
            'A': {'A'},
            'B': {'C'},
            'C': set()
        }
        self.assertEqual(get_cycles(graph_dict), [['A']])

    def test_empty_graph(self):
        graph_dict = {}
        self.assertEqual(get_cycles(graph_dict), [])

    def test_specified_vertices_no_cycles(self):
        graph_dict = {
            'A': {'B'},
            'B': {'C'},
            'C': {'D'},
            'D': set()
        }
        vertices = ['A', 'B']
        self.assertEqual(get_cycles(graph_dict, vertices), [])

